import jsPDF from "jspdf";

const LOGO_BASE64 = "";

export async function gerarPDF(resultado: string, dadosAluno: {
  idade: string;
  peso: string;
  altura: string;
  dias: string;
  objetivo: string;
  nivel: string;
}) {
  const pdf = new jsPDF("p", "mm", "a4");
  const pw = pdf.internal.pageSize.getWidth();   // 210mm
  const ph = pdf.internal.pageSize.getHeight();  // 297mm

  const marginX = 15;
  const contentWidth = pw - marginX * 2;
  let y = 0;

  // Cores
  const preto: [number, number, number] = [0, 0, 0];
  const vermelho: [number, number, number] = [220, 38, 38];
  const vermelhoEscuro: [number, number, number] = [150, 20, 20];
  const branco: [number, number, number] = [255, 255, 255];
  const cinzaClaro: [number, number, number] = [200, 200, 200];
  const cinzaMedio: [number, number, number] = [120, 120, 120];
  const cinzaEscuro: [number, number, number] = [30, 30, 30];

  const novaPagina = () => {
    pdf.addPage();
    // Fundo preto na nova página
    pdf.setFillColor(...preto);
    pdf.rect(0, 0, pw, ph, "F");
    // Linha vermelha topo
    pdf.setFillColor(...vermelho);
    pdf.rect(0, 0, pw, 1.5, "F");
    y = 20;
  };

  const checarPagina = (espaco: number) => {
    if (y + espaco > ph - 15) novaPagina();
  };

  // ─── CAPA ───────────────────────────────────────────────────────────────
  // Fundo preto total
  pdf.setFillColor(...preto);
  pdf.rect(0, 0, pw, ph, "F");

  // Gradiente simulado - retângulo vermelho escuro no topo
  pdf.setFillColor(...vermelhoEscuro);
  pdf.rect(0, 0, pw, 80, "F");

  // Fundo preto sobre o gradiente
  pdf.setFillColor(...preto);
  pdf.rect(0, 20, pw, 60, "F");

  // Logo centralizada
  try {
    pdf.addImage(`data:image/jpeg;base64,${LOGO_BASE64}`, "JPEG", pw / 2 - 25, 15, 50, 50);
  } catch (e) {
    // fallback se imagem falhar
  }

  // Nome do projeto
  pdf.setFont("helvetica", "bold");
  pdf.setFontSize(32);
  pdf.setTextColor(...vermelho);
  pdf.text("PROJETO 90D", pw / 2, 80, { align: "center" });

  // Subtítulo
  pdf.setFontSize(13);
  pdf.setTextColor(...branco);
  pdf.setFont("helvetica", "normal");
  pdf.text("PLANO DE TREINAMENTO PERSONALIZADO", pw / 2, 90, { align: "center" });

  // Linha divisória
  pdf.setDrawColor(...vermelho);
  pdf.setLineWidth(0.8);
  pdf.line(marginX + 20, 96, pw - marginX - 20, 96);

  // Dados do aluno - card escuro
  pdf.setFillColor(...cinzaEscuro);
  pdf.roundedRect(marginX, 103, contentWidth, 65, 3, 3, "F");
  pdf.setDrawColor(...vermelho);
  pdf.setLineWidth(0.4);
  pdf.roundedRect(marginX, 103, contentWidth, 65, 3, 3, "S");

  // Título do card
  pdf.setFont("helvetica", "bold");
  pdf.setFontSize(10);
  pdf.setTextColor(...vermelho);
  pdf.text("DADOS DO ALUNO", marginX + 8, 113);

  // Linha abaixo do título
  pdf.setDrawColor(...vermelhoEscuro);
  pdf.setLineWidth(0.3);
  pdf.line(marginX + 8, 115, pw - marginX - 8, 115);

  const objetivo = dadosAluno.objetivo === "hipertrofia" ? "Hipertrofia" :
    dadosAluno.objetivo === "definicao" ? "Definição" : "Recomposição";
  const nivel = dadosAluno.nivel === "iniciante" ? "Iniciante" :
    dadosAluno.nivel === "intermediario" ? "Intermediário" : "Avançado";
  const imc = (Number(dadosAluno.peso) / ((Number(dadosAluno.altura) / 100) ** 2)).toFixed(1);

  const col1 = marginX + 8;
  const col2 = pw / 2 + 5;

  const dadosLinhas = [
    [["Idade:", `${dadosAluno.idade} anos`], ["Objetivo:", objetivo]],
    [["Peso:", `${dadosAluno.peso} kg`], ["Nível:", nivel]],
    [["Altura:", `${dadosAluno.altura} cm`], ["Dias/semana:", `${dadosAluno.dias} dias`]],
    [["IMC:", imc], ["", ""]],
  ];

  let dy = 124;
  dadosLinhas.forEach(([esq, dir]) => {
    pdf.setFont("helvetica", "bold");
    pdf.setFontSize(9);
    pdf.setTextColor(...cinzaClaro);
    pdf.text(esq[0], col1, dy);
    pdf.setFont("helvetica", "normal");
    pdf.setTextColor(...branco);
    pdf.text(esq[1], col1 + 22, dy);

    if (dir[0]) {
      pdf.setFont("helvetica", "bold");
      pdf.setTextColor(...cinzaClaro);
      pdf.text(dir[0], col2, dy);
      pdf.setFont("helvetica", "normal");
      pdf.setTextColor(...branco);
      pdf.text(dir[1], col2 + 28, dy);
    }
    dy += 11;
  });

  // Data de geração
  pdf.setFont("helvetica", "italic");
  pdf.setFontSize(8);
  pdf.setTextColor(...cinzaMedio);
  const hoje = new Date().toLocaleDateString("pt-BR", { day: "2-digit", month: "long", year: "numeric" });
  pdf.text(`Gerado em ${hoje}`, pw / 2, 177, { align: "center" });

  // Frase motivacional na capa
  pdf.setFillColor(...vermelhoEscuro);
  pdf.rect(marginX, 185, contentWidth, 18, "F");
  pdf.setFont("helvetica", "bold");
  pdf.setFontSize(11);
  pdf.setTextColor(...branco);
  pdf.text("\"90 DIAS PODEM MUDAR O SEU CORPO PARA SEMPRE.\"", pw / 2, 196, { align: "center" });

  // ─── CONTEÚDO ─────────────────────────────────────────────────────────
  novaPagina();

  const linhas = resultado.split("\n");
  let i = 0;

  while (i < linhas.length) {
    const linha = linhas[i].trim();

    // Título principal (# ou ##)
    if (linha.startsWith("# ") || linha.startsWith("## ")) {
      checarPagina(20);
      const texto = linha.replace(/^#{1,2} /, "");
      pdf.setFillColor(...vermelhoEscuro);
      pdf.rect(marginX, y - 5, contentWidth, 14, "F");
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(14);
      pdf.setTextColor(...branco);
      pdf.text(texto.toUpperCase(), pw / 2, y + 4, { align: "center" });
      y += 16;
    }

    // Seção (### ou ####)
    else if (linha.startsWith("### ") || linha.startsWith("#### ")) {
      checarPagina(16);
      const texto = linha.replace(/^#{3,4} /, "");
      // Barra vermelha lateral
      pdf.setFillColor(...vermelho);
      pdf.rect(marginX, y - 4, 3, 10, "F");
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(11);
      pdf.setTextColor(...vermelho);
      pdf.text(texto.toUpperCase(), marginX + 7, y + 3);
      // Linha abaixo
      pdf.setDrawColor(...vermelhoEscuro);
      pdf.setLineWidth(0.3);
      pdf.line(marginX + 7, y + 5, pw - marginX, y + 5);
      y += 14;
    }

    // Exercício em negrito (**Nome**)
    else if (linha.startsWith("**") && linha.endsWith("**")) {
      const nome = linha.replace(/\*\*/g, "");
      const props: { label: string; valor: string }[] = [];
      let j = i + 1;
      while (j < linhas.length) {
        const sub = linhas[j].trim();
        if (sub.startsWith("- Séries:") || sub.startsWith("- Repetições:") ||
          sub.startsWith("- Descanso:") || sub.startsWith("- Tempo:")) {
          const [label, ...resto] = sub.replace("- ", "").split(":");
          props.push({ label: label.trim(), valor: resto.join(":").trim() });
          j++;
        } else break;
      }

      const cardH = 22 + (props.length > 0 ? 14 : 0);
      checarPagina(cardH + 4);

      // Card do exercício
      pdf.setFillColor(...cinzaEscuro);
      pdf.roundedRect(marginX, y, contentWidth, cardH, 2, 2, "F");
      pdf.setDrawColor(50, 50, 50);
      pdf.setLineWidth(0.3);
      pdf.roundedRect(marginX, y, contentWidth, cardH, 2, 2, "S");

      // Nome do exercício
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(10);
      pdf.setTextColor(...branco);
      pdf.text(nome, marginX + 5, y + 8);

      // Badges das propriedades
      if (props.length > 0) {
        const badgeW = contentWidth / props.length - 4;
        props.forEach((p, idx) => {
          const bx = marginX + idx * (badgeW + 4) + 2;
          const by = y + 12;
          pdf.setFillColor(15, 15, 15);
          pdf.roundedRect(bx, by, badgeW, 10, 1, 1, "F");
          pdf.setFont("helvetica", "normal");
          pdf.setFontSize(7);
          pdf.setTextColor(...cinzaMedio);
          pdf.text(p.label.toUpperCase(), bx + badgeW / 2, by + 4, { align: "center" });
          pdf.setFont("helvetica", "bold");
          pdf.setFontSize(8);
          pdf.setTextColor(...vermelho);
          pdf.text(p.valor, bx + badgeW / 2, by + 8.5, { align: "center" });
        });
      }

      y += cardH + 4;
      i = j;
      continue;
    }

    // Item de lista
    else if (linha.startsWith("- ") && !linha.match(/^- (Séries|Repetições|Descanso|Tempo):/)) {
      const texto = linha.replace(/^- /, "").replace(/\*\*/g, "");
      const wrapped = pdf.splitTextToSize(`• ${texto}`, contentWidth - 8);
      checarPagina(wrapped.length * 5 + 3);
      pdf.setFont("helvetica", "normal");
      pdf.setFontSize(9);
      pdf.setTextColor(...cinzaClaro);
      pdf.text(wrapped, marginX + 4, y);
      y += wrapped.length * 5 + 2;
    }

    // Separador ---
    else if (linha === "---") {
      checarPagina(8);
      pdf.setDrawColor(...vermelhoEscuro);
      pdf.setLineWidth(0.4);
      pdf.line(marginX, y, pw - marginX, y);
      y += 8;
    }

    // Linha vazia
    else if (linha === "") {
      y += 3;
    }

    // Texto normal
    else {
      const textoLimpo = linha.replace(/\*\*/g, "");
      // Detecta se é um número de seção tipo "1. Análise..."
      const ehSecao = /^\d+\.\s/.test(textoLimpo);
      const wrapped = pdf.splitTextToSize(textoLimpo, contentWidth - 4);
      checarPagina(wrapped.length * 5 + 3);

      if (ehSecao) {
        pdf.setFont("helvetica", "bold");
        pdf.setFontSize(10);
        pdf.setTextColor(...vermelho);
      } else {
        pdf.setFont("helvetica", "normal");
        pdf.setFontSize(9);
        pdf.setTextColor(...cinzaClaro);
      }

      pdf.text(wrapped, marginX + 2, y);
      y += wrapped.length * 5 + 3;
    }

    i++;
  }

  pdf.save("Projeto90D-Plano-Personalizado.pdf");
}